//! Synthetic vendor "driver" — a decoder self-test with no backing file.
//!
//! Ported from `openslide-vendor-synthetic.c`. The C driver embeds tiny (16×16)
//! test payloads, one per codec, each zlib-compressed. `open` inflates and
//! decodes every one to prove the library's decoders are wired up, then lays the
//! rendered images out as a single 1-row strip of 16×16 tiles. It is gated
//! behind an empty filename + the `synthetic` debug flag, so it never triggers
//! for real input.
//!
//! ponytail: this port includes only the items whose decoders exist here (JPEG,
//! TIFF JPEG/LZW classic+Big, XML, Zstd). Add the bmp/png/j2k/dicom items when
//! `decode/{bmp,png,jp2k,dicom}.rs` land.

use crate::decode::TileDecoder;
use crate::decode::jpeg::JpegDecoder;
use crate::decode::tiff::{TiffLike, tags};
use crate::decode::{deflate, xml};
use crate::error::{OpenSlideError, Result};
use crate::grid::simple::SimpleGrid;
use crate::io::SlideReader;
use crate::level::LevelInfo;
use crate::properties::{self, Properties};
use crate::vendor::{LevelData, SlideData};

const IMAGE_PIXELS: i64 = 16;
const IMAGE_PX: usize = (IMAGE_PIXELS * IMAGE_PIXELS) as usize; // 256 pixels/tile

#[derive(Clone, Copy)]
enum Kind {
    Jpeg,
    Tiff,
    Xml,
    Zstd,
}

struct Item {
    name: &'static str,
    description: &'static str,
    is_valid: bool,
    is_image: bool,
    kind: Kind,
    /// zlib-compressed payload; inflates to the raw codec bytes.
    data: &'static [u8],
}

